//! Deliberately wrong solution — `aggregate`, unbounded fan-out.
//!
//! This is a mutant input for the harness, not an example: it ignores the
//! four-in-flight bound and starts every fetch at once. The oracle's
//! `at_most_four_fetches_are_in_flight` test must fail it. It is never built by
//! the estate workspace (this directory is not a member), so it is not held to
//! the estate lint contract.

use std::time::Duration;

use ai_task_support::{FetchError, Fetcher};
use lgwks_bot::rt::task::join_all_bounded;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    let _ = deadline;
    let futures = ids.into_iter().map(|id| {
        let fetcher = fetch.clone();
        async move { fetcher.fetch(id).await }
    });
    let results = join_all_bounded(usize::MAX, futures).await;
    let mut sum: u64 = 0;
    for result in results {
        match result {
            Ok(value) => sum = sum.saturating_add(value),
            Err(FetchError::Failed { id }) => return Err(SolveError::Fetch { id }),
        }
    }
    Ok(sum)
}

//! Deliberately wrong solution — `pipeline`, detached spawn.
//!
//! This is a mutant input for the harness, not an example. The pipeline runs on
//! a `JoinSet` handed to a process-lifetime holder instead of being owned by the
//! call, so the stages are detached from the caller's future: dropping `solve`
//! leaves them running. The oracle's
//! `dropping_the_future_leaves_no_stage_live` test must fail it. Everything else
//! is correct, so it is the drop clause and only the drop clause that catches
//! the leak. It is never built by the estate workspace (this directory is not a
//! member), so it is not held to the estate lint contract.

use std::sync::{Mutex, OnceLock};
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::sync::oneshot;
use lgwks_bot::rt::task::{JoinSet, join_all_bounded};
use lgwks_bot::rt::time;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// The mutation: task sets that outlive every call that started them.
static DETACHED: OnceLock<Mutex<Vec<JoinSet<()>>>> = OnceLock::new();

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let mut set = JoinSet::new();
    let (sender, receiver) = oneshot::channel();
    let worker = stage.clone();
    set.spawn(async move {
        let _ = sender.send(pipeline(worker, deadline).await);
    });
    if let Ok(mut held) = DETACHED.get_or_init(|| Mutex::new(Vec::new())).lock() {
        held.push(set);
    }
    match receiver.await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Cancelled),
    }
}

async fn pipeline(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let work = async move {
        let names = [StageName::FetchA, StageName::FetchB];
        let futures: Vec<_> = names
            .into_iter()
            .map(|name| {
                let stage = stage.clone();
                async move { run_stage(stage, name).await }
            })
            .collect();
        let fetched = join_all_bounded(2, futures).await;
        for result in fetched {
            if let Err(error) = result {
                return Err(error);
            }
        }
        let _combined = run_stage(stage.clone(), StageName::Combine).await?;
        let published = run_stage(stage, StageName::Publish).await?;
        Ok(Published::from(published))
    };
    match time::timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn run_stage(stage: Stage, name: StageName) -> Result<Artifact, PipelineError> {
    stage
        .run(name)
        .await
        .map_err(|_| PipelineError::Stage { name })
}
